import sys
import math

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    if n > 20:
        print(0)
    else:
        points = []
        index = 1
        for _ in range(n):
            point = list(map(int, input_data[index:index+5]))
            index += 5
            points.append(point)
        valid = []
        for i in range(n):
            for j in range(n):
                if i != j:
                    for k in range(j + 1, n):
                        if i != k:
                            if compute_angle(points[i], points[j], points[k]) < 90:
                                break
                    else:
                        continue
                    break
            else:
                valid.append(i + 1)
        print(len(valid))
        for v in valid:
            print(v)

def compute_angle(p1, p2, p3):
    dot = 0.0
    a_len = 0.0
    b_len = 0.0
    for i in range(len(p1)):
        v1 = p2[i] - p1[i]
        v2 = p3[i] - p1[i]
        dot += v1 * v2
        a_len += v1 * v1
        b_len += v2 * v2
    if a_len == 0 or b_len == 0:
        return 0
    angle_rad = math.acos(dot / math.sqrt(a_len * b_len))
    return 180 * angle_rad / math.pi

if __name__ == "__main__":
    main()

